// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new PrivateBank(address(lg));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, c.MinDeposit(), 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // Rule: a completed deposit of >= MinDeposit must record a History entry.
        bool logged;
        try lg.History(0) returns (
            address,
            string memory,
            uint256,
            uint256
        ) {
            logged = true;
        } catch {
            logged = false;
        }
        assertTrue(logged);
    }
}
